52	/**
53	 * Reads the pasted lines (name,grade) and checks each with the form's rules: a name, a grade of A, B
54	 * or C, and a name not repeated in the paste (ignoring case; names are trimmed). A name already on
55	 * the sheet updates that person's grade; any other name adds a person. Blank lines are skipped. Any
56	 * bad line refuses the whole import.
57	 */
58	public class CheckImport {
59	
60	    private static final Set<String> GRADES = Set.of("A", "B", "C");
61	
62	    public void check(@PathVariable("sheetId") String sheetId, @RequestBody ImportRequest request,
63	            PersonRepository repository, Out<ImportedPeople> importedOut) throws InvalidImportException {
64	        String sheet = sheetId.trim();
65	        Map<String, Person> existing = new HashMap<>();
66	        repository.findBySheetIdOrderByIdAsc(sheet).forEach((p) -> existing.putIfAbsent(key(p.getName()), p));
67	        Set<String> seen = new HashSet<>();
68	        String[] lines = request == null || request.text() == null ? new String[0] : request.text().split("\\R", -1);
69	        List<Person> people = new ArrayList<>();
70	        List<Person> updated = new ArrayList<>();
71	        List<String> grades = new ArrayList<>();
72	        List<Integer> errors = new ArrayList<>();
73	        for (int i = 0; i < lines.length; i++) {
74	            String line = lines[i];
75	            if (line.isBlank()) {
76	                continue;
77	            }
78	            int comma = line.indexOf(',');
79	            String name = (comma < 0 ? line : line.substring(0, comma)).trim();
80	            String grade = comma < 0 ? "" : line.substring(comma + 1).trim();
81	            if (name.isEmpty() || !GRADES.contains(grade) || !seen.add(key(name))) {
82	                errors.add(i + 1);
83	                continue;
84	            }
85	            Person person = existing.get(key(name));
86	            if (person != null) {
87	                updated.add(person);
88	            } else {
89	                person = new Person(sheet);
90	                person.setName(name);
91	            }
92	            people.add(person);
93	            grades.add(grade);
94	        }
95	        if (!errors.isEmpty()) {
96	            throw new InvalidImportException(errors);
97	        }
98	        // Only now set the grades, so a refused import leaves the sheet's people untouched.
99	        for (int i = 0; i < people.size(); i++) {
100	            people.get(i).setGrade(grades.get(i));
101	        }
102	        importedOut.set(new ImportedPeople(people, updated));
103	    }
104	
105	    private static String key(String name) {
106	        return name.trim().toLowerCase(Locale.ROOT);
107	    }
108	}
