782	/**
783	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
784	 * so tests can assert side-effects by reading that file — the second test-assertion channel
785	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
786	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
787	 *
788	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
789	 * SYNC) so a test reads the record immediately.
790	 */
791	@Service
792	public class Audit {
793	
794	    private final Path file;
795	
796	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
797	        this.file = Path.of(path);
798	    }
799	
800	    /** Append one audit record. Tests assert the exact line(s) in the file. */
801	    public synchronized void record(String entry) {
802	        try {
803	            Path parent = file.toAbsolutePath().getParent();
804	            if (parent != null) {
805	                Files.createDirectories(parent);
806	            }
807	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
808	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
809	        } catch (IOException e) {
810	            throw new UncheckedIOException(e);
811	        }
812	    }
813	
814	    /** Remove the audit file. */
815	    public synchronized void clear() {
816	        try {
817	            Files.deleteIfExists(file);
818	        } catch (IOException e) {
819	            throw new UncheckedIOException(e);
820	        }
821	    }
822	}
