import { useQuery } from '@tanstack/react-query';
import { getJson, postJson, putJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

// Amounts travel as strings with two decimals ("13.50"); sums are added up in whole cents so no
// floating-point error shows.
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when opened, the next on the sheet; null for a draft or a voided claim. */
  number: number | null;
  /** Fixed when settled (two decimals); null while live, or when no rate applied at settling. */
  settledDue: string | null;
  /** The user who opened it; null for a draft. */
  openedBy: string | null };
export type ClaimInput = { amount: string; date: string; note: string };

/** 0.00 or more, with up to two decimals. */
export const AMOUNT = /^\d+(\.\d{1,2})?$/;

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;
export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The active sheet's claims, newest first. */
export function useClaims() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: claimsKey(sheet ?? ''),
    queryFn: () => getJson<{ claims: Claim[] }>(`${base(sheet!)}/claims`).then((r) => r.claims),
    enabled: !!sheet,
  });
}

export const addClaim = (sheet: string, user: string, personId: number, input: ClaimInput) =>
  postJson<Claim>(`${base(sheet)}/people/${personId}/claims`, input, user);

export const updateClaim = (sheet: string, user: string, id: number, input: ClaimInput) =>
  putJson<Claim>(`${base(sheet)}/claims/${id}`, input, user);

// A claim starts DRAFT; it can be opened, then settled; a DRAFT or OPEN claim can be voided.
// SETTLED and VOID are final. The server refuses a change not allowed; the screen refuses it first.
export type ClaimAction = 'open' | 'settle' | 'void';
export const CLAIM_ACTIONS: ClaimAction[] = ['open', 'settle', 'void'];
const ALLOWED: Record<ClaimAction, ClaimStatus[]> = { open: ['DRAFT'], settle: ['OPEN'], void: ['DRAFT', 'OPEN'] };
export const canTake = (claim: Claim, action: ClaimAction) => ALLOWED[action].includes(claim.status);

/** Four eyes: the user who opened a claim cannot settle it. */
export const selfSettle = (claim: Claim, user: string, action: ClaimAction) =>
  action === 'settle' && claim.openedBy != null && claim.openedBy === user.trim();

export const claimAction = (sheet: string, user: string, id: number, action: ClaimAction) =>
  postJson<Claim>(`${base(sheet)}/claims/${id}/${action}`, {}, user);

/** Whether a claim counts toward claimed, due-total and every total: only OPEN and SETTLED do. */
export const counts = (claim: Claim) => claim.status === 'OPEN' || claim.status === 'SETTLED';

const cents = (amount: string) => {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number((frac + '00').slice(0, 2));
};

/** The amounts of the claims that count (OPEN and SETTLED) added up, shown with two decimals. */
export function total(claims: Claim[]): string {
  const sum = claims.filter(counts).reduce((n, c) => n + cents(c.amount), 0);
  return `${Math.floor(sum / 100)}.${String(sum % 100).padStart(2, '0')}`;
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { NA, claimDueCents, show, usePersonRate } from '../rates/rates';
import { AMOUNT, CLAIM_ACTIONS, addClaim, canTake, claimAction, claimsKey, selfSettle, total, updateClaim, useClaims } from './claims';
import type { Claim, ClaimAction, ClaimInput } from './claims';

const EMPTY: ClaimInput = { amount: '', date: '', note: '' };
const LABEL: Record<ClaimAction, string> = { open: 'Open', settle: 'Settle', void: 'Void' };
const showDue = (due: bigint | undefined) => (due === undefined ? NA : show(due));
const DONE: Record<ClaimAction, string> = { open: 'opened', settle: 'settled', void: 'voided' };

function ClaimColumns() {
  return (
    <>
      <th>Claimed</th>
      <th>Claims</th>
    </>
  );
}

// A person's claimed total, and their claims: a form that adds a claim or, once a claim's edit is
// pressed, edits it; and the claims listed newest first, each with its status and the buttons that
// change it. An empty date means the sheet's today. A refused status change shows on its claim.
function PersonClaims({ personId }: { personId: number }) {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === personId);
  const rateOf = usePersonRate();
  const [editing, setEditing] = useState<number | undefined>();
  const [form, setForm] = useState<ClaimInput>(EMPTY);
  const [error, setError] = useState('');
  const [claimErrors, setClaimErrors] = useState<Record<number, string>>({});
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const clearClaimError = (id: number) =>
    setClaimErrors(({ [id]: _, ...rest }) => rest);
  const refuse = (id: number, message: string) => setClaimErrors((e) => ({ ...e, [id]: message }));

  const act = useMutation({
    mutationFn: ({ claim, action }: { claim: Claim; action: ClaimAction }) =>
      claimAction(sheet!, user, claim.id, action),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet!) }),
    onError: async (_e, { claim, action }) => {
      refuse(claim.id, `This claim cannot be ${DONE[action]}.`);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet!) });
    },
  });

  const take = (claim: Claim, action: ClaimAction) => {
    clearClaimError(claim.id);
    if (!canTake(claim, action)) {
      refuse(claim.id, `A ${claim.status} claim cannot be ${DONE[action]}.`);
      return;
    }
    if (selfSettle(claim, user, action)) {
      refuse(claim.id, 'The user who opened a claim cannot settle it.');
      return;
    }
    act.mutate({ claim, action });
  };

  const save = useMutation({
    mutationFn: (input: ClaimInput) =>
      editing !== undefined ? updateClaim(sheet!, user, editing, input) : addClaim(sheet!, user, personId, input),
    onSuccess: async () => {
      setForm(EMPTY);
      setEditing(undefined);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet!) });
    },
    onError: () => setError('The claim could not be saved: the amount must be 0.00 or more, with up to two decimals.'),
  });

  const change = (patch: Partial<ClaimInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const open = (claim: Claim) => {
    clearClaimError(claim.id);
    setEditing(claim.id);
    setForm({ amount: claim.amount, date: claim.date, note: claim.note });
    setError('');
  };

  const cancel = () => {
    setEditing(undefined);
    setForm(EMPTY);
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!AMOUNT.test(form.amount.trim())) {
      setError('The amount must be a number of 0.00 or more, with up to two decimals.');
      return;
    }
    once(() => save.mutateAsync({ amount: form.amount.trim(), date: form.date, note: form.note }));
  };

  return (
    <>
      <td data-testid="person-claimed">{total(claims)}</td>
      <td>
        <form data-testid="claim-form" onSubmit={submit}>
          <input
            data-testid="claim-form-amount"
            placeholder="Amount"
            inputMode="decimal"
            value={form.amount}
            onChange={(e) => change({ amount: e.target.value })}
          />
          <input
            type="date"
            data-testid="claim-form-date"
            value={form.date}
            onChange={(e) => change({ date: e.target.value })}
          />
          <input
            data-testid="claim-form-note"
            placeholder="Note"
            value={form.note}
            onChange={(e) => change({ note: e.target.value })}
          />
          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
            {editing !== undefined ? 'Save claim' : 'Add claim'}
          </button>
          {editing !== undefined && (
            <button type="button" data-testid="claim-form-cancel" onClick={cancel}>
              Cancel
            </button>
          )}
          {error && <span data-testid="claim-form-error">{error}</span>}
        </form>
        <ul data-testid="claim-list">
          {claims.map((c) => (
            <li key={c.id} data-testid={`claim-row-${c.id}`}>
              <span data-testid="claim-amount">{c.amount}</span>{' '}
              <span data-testid="claim-date">{c.date}</span>{' '}
              <span data-testid="claim-note">{c.note}</span>{' '}
              <span data-testid="claim-due">{showDue(claimDueCents(c, rateOf(personId, c.date)))}</span>{' '}
              <span data-testid="claim-status">{c.status}</span>{' '}
              <span data-testid="claim-number">{c.number ?? ''}</span>{' '}
              <span data-testid="claim-opened-by">{c.openedBy ?? ''}</span>{' '}
              <button type="button" data-testid="claim-edit" onClick={() => open(c)}>
                Edit
              </button>
              {CLAIM_ACTIONS.map((a) => (
                <button key={a} type="button" data-testid={`claim-${a}`} onClick={() => take(c, a)}>
                  {LABEL[a]}
                </button>
              ))}
              {claimErrors[c.id] && <span data-testid="claim-error">{claimErrors[c.id]}</span>}
            </li>
          ))}
        </ul>
      </td>
    </>
  );
}

// The sheet's claimed-total: everyone's claimed added up (only OPEN and SETTLED claims count).
function ClaimedTotal() {
  const [sheet] = useCurrentSheet();
  const claims = useClaims();
  if (!sheet) return null;
  return (
    <section data-testid="rollup">
      Claimed total <strong data-testid="rollup-claimed-total">{total(claims.data ?? [])}</strong>
    </section>
  );
}

export const contributions = [
  PersonColumns.fill({ order: 10, Component: ClaimColumns }),
  PersonCells.fill({ order: 10, Component: PersonClaims }),
  HomeMain.fill({ order: 20, Component: ClaimedTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import type { Claim } from '../claims/claims';
import { usePeople } from '../people/people';
import { useCurrentSheet, useSheetToday } from '../session/session';

// A rate is a percent with two decimals ("12.50") for a grade from a from-date on (null: from the
// beginning of time); a grade may have several. A date uses the rate whose from-date is the latest on
// or before it; a date before every rate of its grade, or a grade with no rate, has none (n/a).
// Due is worked out in whole cents and hundredths of a percent with BigInt, so no floating-point
// error shows: amount × rate / 100, rounded half to even to two decimals.
export type Rate = { grade: string; rate: string; from: string | null };
export type RateInput = { grade: string; rate: string; from: string };

/** 0.00 or more, with up to two decimals. */
export const PERCENT = /^\d{1,5}(\.\d{1,2})?$/;

/** What a due shows when its grade has no rate. */
export const NA = 'n/a';

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/rates`;
export const ratesKey = (sheet: string) => ['sheet', sheet, 'rates'] as const;

/** The active sheet's rates, by grade. */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesKey(sheet ?? ''),
    queryFn: () => getJson<{ rates: Rate[] }>(base(sheet!)).then((r) => r.rates),
    enabled: !!sheet,
  });
}

export const setRate = (sheet: string, user: string, input: RateInput) => postJson<Rate>(base(sheet), input, user);

/** A two-decimal string as a whole number of hundredths. */
export const hundredths = (value: string): bigint => {
  const [whole, frac = ''] = value.split('.');
  return BigInt(whole) * 100n + BigInt((frac + '00').slice(0, 2));
};

/** Hundredths shown with two decimals. */
export const show = (n: bigint): string => {
  const sign = n < 0n ? '-' : '';
  const abs = n < 0n ? -n : n;
  return `${sign}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
};

/** The due on an amount at a rate, in cents: amount × rate / 100, rounded half to even. */
export function dueCents(amount: string, rate: string): bigint {
  const product = hundredths(amount) * hundredths(rate); // cents × hundredths of a percent
  const sign = product < 0n ? -1n : 1n;
  const abs = sign * product;
  const whole = abs / 10000n;
  const rest = abs % 10000n;
  const up = rest > 5000n || (rest === 5000n && whole % 2n === 1n);
  return sign * (up ? whole + 1n : whole);
}

/** A claim's due in cents: a settled claim's is the one fixed when it was settled; an open or draft
 *  claim's is live, at its grade's rate in force on the claim's date. Undefined for n/a. */
export function claimDueCents(claim: Claim, rate: string | undefined): bigint | undefined {
  if (claim.status === 'SETTLED') return claim.settledDue === null ? undefined : hundredths(claim.settledDue);
  return rate === undefined ? undefined : dueCents(claim.amount, rate);
}

/** The grade's rate (two decimals) in force on a date (yyyy-mm-dd), or undefined when none applies. */
export function rateOn(rates: Rate[], grade: string | undefined, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.rate;
}

/** The rate (two decimals) for a grade in force on a date (default: the sheet's today), or undefined. */
export function useGradeRate() {
  const rates = useRates().data ?? [];
  const today = useSheetToday();
  return (grade: string | undefined, date: string | undefined = today) => rateOn(rates, grade, date);
}

/** The rate for a person's grade in force on a date (default: the sheet's today), looked up by person id. */
export function usePersonRate() {
  const people = usePeople().data ?? [];
  const rateOf = useGradeRate();
  return (personId: number, date?: string) => rateOf(people.find((p) => p.id === personId)?.grade, date);
}
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson, putJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import { asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

export type Person = { id: number; name: string; grade: string; version: number };
/** An edit carries the version of the person it was loaded from; the server refuses it (409) when
 *  someone else has saved the person since. */
export type PersonInput = { name: string; grade: string; version?: number };

const base = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;
export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The active sheet's people, in the order they were added. */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleKey(sheet ?? ''),
    queryFn: () => getJson<{ people: Person[] }>(base(sheet!)).then((r) => r.people),
    enabled: !!sheet,
  });
}

export const addPerson = (sheet: string, user: string, input: PersonInput) =>
  postJson<Person>(base(sheet), input, user);

export const updatePerson = (sheet: string, user: string, id: number, input: PersonInput) =>
  putJson<Person>(`${base(sheet)}/${id}`, input, user);

/** The outcome of an import: the counts added and updated, or the numbers of the lines refused
 *  (nothing imported). */
export type ImportResult = { added: number; updated: number; errors: number[] };

/** Imports people pasted as lines of name,grade; a refusal (400) carries the bad line numbers. */
export const importPeople = (sheet: string, user: string, text: string) =>
  postJson<ImportResult>(`${base(sheet)}/import`, { text }, user);

/** The person open in the editor (by id), kept in the URL. */
export const useEditingPerson = () => useSearchParam('editPerson', asString);

