const EMPTY: PersonInput = { name: '', grade: 'A' };

// The sheet's people: a form that adds a person or, once a person's editor is opened, edits them;
// and the list of people in the order they were added. The editor remembers the version it loaded:
// when someone else has saved the person since, the save is refused and the form shows their values.
function People() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const people = usePeople();
  const [editing, setEditing] = useEditingPerson();
  const [form, setForm] = useState<PersonInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (input: PersonInput) =>
      editing ? updatePerson(sheet!, user, Number(editing), input) : addPerson(sheet!, user, input),
    onSuccess: async () => {
      setForm(EMPTY);
      setEditing(undefined);
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
    },
    onError: async (e) => {
      if (!(editing && e instanceof HttpError && e.status === 409)) {
        setError('The person could not be saved: a name is required and must not already be in use.');
        return;
      }
      setError('Someone else saved this person meanwhile; their values are shown. Nothing was saved.');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
      const current = queryClient.getQueryData<Person[]>(peopleKey(sheet!))?.find((p) => p.id === Number(editing));
      if (current) setForm({ name: current.name, grade: current.grade, version: current.version });
    },
  });

  if (!sheet) return null;

  const change = (patch: Partial<PersonInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const open = (person: Person) => {
    setEditing(String(person.id));
    setForm({ name: person.name, grade: person.grade, version: person.version });
    setError('');
  };

  const cancel = () => {
    setEditing(undefined);
    setForm(EMPTY);
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!form.name.trim()) {
      setError('A person needs a name.');
      return;
    }
    once(() => save.mutateAsync(form));
  };

  return (
    <section data-testid="people">
      <h2>People</h2>
      <form data-testid="person-form" onSubmit={submit}>
        <input
          data-testid="person-form-name"
          placeholder="Name"
          value={form.name}
          onChange={(e) => change({ name: e.target.value })}
        />
        <select
          data-testid="person-form-grade"
          value={form.grade}
          onChange={(e) => change({ grade: e.target.value })}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing ? 'Save' : 'Add person'}
        </button>
        {editing && (
          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
            Cancel
          </button>
        )}
        {error && <span data-testid="person-form-error">{error}</span>}
      </form>
      <table data-testid="people-list">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <PersonColumns.Slot />
            <th />
          </tr>
        </thead>
        <tbody>
          {(people.data ?? []).map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <PersonCells.Slot personId={p.id} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 10, Component: People });

// Import people pasted as lines of name,grade. The server checks every line first; when any is bad
// nothing is imported and each bad line is marked by its number, otherwise the counts added and
// updated (a name already on the sheet updates that person's grade) are shown.
function ImportPeople() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const [text, setText] = useState('');
  const [result, setResult] = useState<ImportResult | null>(null);
  const [failed, setFailed] = useState(false);
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const run = useMutation({
    mutationFn: (input: string) => importPeople(sheet!, user, input),
    onSuccess: async (r) => {
      setResult(r);
      setText('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
    },
    onError: (e) => {
      const body = e instanceof HttpError ? (e.body as ImportResult | undefined) : undefined;
      if (body && Array.isArray(body.errors)) setResult({ added: 0, updated: 0, errors: body.errors });
      else setFailed(true);
    },
  });

  if (!sheet) return null;

  const clear = () => {
    setResult(null);
    setFailed(false);
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    clear();
    once(() => run.mutateAsync(text));
  };

  return (
    <section data-testid="import">
      <h2>Import people</h2>
      <form data-testid="import-form" onSubmit={submit}>
        <textarea
          data-testid="import-text"
          placeholder="name,grade — one person per line"
          rows={4}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            clear();
          }}
        />
        <button type="submit" data-testid="import-submit" disabled={run.isPending}>
          Import
        </button>
      </form>
      {result && (
        <p>
          Added <span data-testid="import-added">{result.added}</span>, updated{' '}
          <span data-testid="import-updated">{result.updated}</span>
          {result.errors.length > 0 && <> — nothing was imported; fix these lines:</>}
        </p>
      )}
      {result && result.errors.length > 0 && (
        <ul>
          {result.errors.map((n) => (
            <li key={n} data-testid={`import-error-${n}`}>
              Line {n}: a name is required, not repeated in the paste, with a grade of A, B or C.
            </li>
          ))}
        </ul>
      )}
      {failed && <span data-testid="import-failed">The import could not be made.</span>}
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 15, Component: ImportPeople });

const DATE = /^\d{4}-\d{2}-\d{2}$/;

const EMPTY: RateInput = { grade: 'A', rate: '', from: '' };

// The sheet's rates: a form that sets a grade's rate from a from-date (none: from the beginning of
// time), replacing any rate it had for that from-date; each grade's rate in force on the sheet's today
// (n/a when none applies); and every rate set, by grade then from-date.
function Rates() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const rateOf = useGradeRate();
  const rates = useRates().data ?? [];
  const [form, setForm] = useState<RateInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (input: RateInput) => setRate(sheet!, user, input),
    onSuccess: async () => {
      setForm((f) => ({ ...f, rate: '', from: '' }));
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheet!) });
    },
    onError: () =>
      setError('The rate could not be set: it must be a percent of 0.00 or more, with up to two decimals, and a date if from is given.'),
  });

  if (!sheet) return null;

  const change = (patch: Partial<RateInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!PERCENT.test(form.rate.trim())) {
      setError('The rate must be a percent of 0.00 or more, with up to two decimals.');
      return;
    }
    const from = form.from.trim();
    if (from !== '' && !DATE.test(from)) {
      setError('The from-date must be a date (yyyy-mm-dd).');
      return;
    }
    once(() => save.mutateAsync({ grade: form.grade, rate: form.rate.trim(), from }));
  };

  return (
    <section data-testid="rates">
      <h2>Rates</h2>
      <form data-testid="rate-form" onSubmit={submit}>
        <select data-testid="rate-form-grade" value={form.grade} onChange={(e) => change({ grade: e.target.value })}>
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
        <input
          data-testid="rate-form-pct"
          placeholder="Percent"
          inputMode="decimal"
          value={form.rate}
          onChange={(e) => change({ rate: e.target.value })}
        />
        <input
          data-testid="rate-form-from"
          type="date"
          placeholder="From (yyyy-mm-dd)"
          value={form.from}
          onChange={(e) => change({ from: e.target.value })}
        />
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {error && <span data-testid="rate-form-error">{error}</span>}
      </form>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate today (%)</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateOf(g) ?? NA}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="rate-history">
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>Rate (%)</th>
          </tr>
        </thead>
        <tbody>
          {rates.map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? 'start'}</td>
              <td data-testid="rate-pct">{r.rate}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

function DueColumn() {
  return <th>Due</th>;
}

/** A person's due-total in cents: the already-rounded figures of their claims that count added up
 *  (0 when none counts). Undefined for n/a: their grade has no rate today and no settled claim keeps
 *  a figure. */
function useDueTotal() {
  const claims = useClaims().data ?? [];
  const rateOf = usePersonRate();
  return (personId: number) => {
    const figures = claims
      .filter((c) => c.personId === personId && counts(c))
      .map((c) => ({ claim: c, due: claimDueCents(c, rateOf(personId, c.date)) }));
    const kept = figures.some((f) => f.claim.status === 'SETTLED' && f.due !== undefined);
    if (rateOf(personId) === undefined && !kept) return undefined;
    return figures.reduce((n, f) => n + (f.due ?? 0n), 0n);
  };
}

// A person's due-total: n/a when their grade has no rate today, unless a settled claim keeps a figure.
function PersonDueTotal({ personId }: { personId: number }) {
  const due = useDueTotal()(personId);
  return <td data-testid="person-due-total">{due === undefined ? NA : show(due)}</td>;
}

// The sheet's due-total: everyone's due-total added up, skipping n/a.
function DueTotal() {
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const dueOf = useDueTotal();
  if (!sheet) return null;
  const sum = people.reduce((n, p) => n + (dueOf(p.id) ?? 0n), 0n);
  return (
    <section data-testid="rollup-due">
      Due total <strong data-testid="rollup-due-total">{show(sum)}</strong>
    </section>
  );
}

export const contributions = [
  HomeMain.fill({ order: 5, Component: Rates }),
  PersonColumns.fill({ order: 20, Component: DueColumn }),
  PersonCells.fill({ order: 20, Component: PersonDueTotal }),
  HomeMain.fill({ order: 21, Component: DueTotal }),
];

// The session lives in the URL: `user` is the signed-in name (no password), `sheet` the active
// sheet id. Every feature that works per sheet or records who did something reads these.
export const useCurrentUser = () => useSearchParam('user', asString);
export const useCurrentSheet = () => useSearchParam('sheet', asString);

// `today` is the sheet's own date (yyyy-mm-dd). Every date decision and every default date in the
// app uses it — never the browser's or server's clock.
export type Sheet = { id: string; today: string };
export const sheetKey = (id: string) => ['sheet', id] as const;

export const loadSheet = (id: string) => postJson<Sheet>(`/api/sheets/${encodeURIComponent(id)}/load`, {});

/** The active sheet, as the store holds it (filled by the sheet picker when it loads a sheet). */
export function useSheet() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: sheetKey(sheet ?? ''),
    queryFn: () => loadSheet(sheet!),
    enabled: !!sheet,
    staleTime: Infinity,
  });
}

/** The active sheet's today (yyyy-mm-dd): use it for every date default and date decision. */
export const useSheetToday = () => useSheet().data?.today;

function SheetPicker() {
  const [user] = useCurrentUser();
  const [sheet, setSheet] = useCurrentSheet();
  const [id, setId] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const load = useMutation({
    mutationFn: (sheetId: string) => loadSheet(sheetId),
    onSuccess: async (loaded) => {
      queryClient.setQueryData(sheetKey(loaded.id), loaded);
      // Re-loading a sheet re-reads everything kept under it from the store.
      await queryClient.invalidateQueries({
        predicate: (q) => q.queryKey[0] === 'sheet' && q.queryKey[1] === loaded.id && q.queryKey.length > 2,
      });
      setSheet(loaded.id);
    },
    onError: () => setError('The sheet could not be loaded.'),
  });

  if (!user) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = id.trim();
    setError('');
    if (!trimmed) {
      setError('Type a sheet id to load.');
      return;
    }
    once(() => load.mutateAsync(trimmed));
  };

  return (
    <form data-testid="sheet-form" onSubmit={submit}>
      <input
        data-testid="sheet-id-input"
        placeholder="Sheet id"
        value={id}
        onChange={(e) => {
          setId(e.target.value);
