 */
export const AppSession = defineSlot('app.session');

/** The home page's main region: the panels kept per sheet (people, ...). */
export const HomeMain = defineSlot('home.main');

/** Extra column headers of the people table, one per contributed column. */
export const PersonColumns = defineSlot('person.columns');

/** Extra cells of a person's row (in the same order as their PersonColumns headers). */
export const PersonCells = defineSlot<{ personId: number }>('person.cells');
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a caller tell one refusal from another (e.g. 409 Conflict). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number, readonly body?: unknown) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    // A refusal may explain itself in a JSON body (e.g. which lines of an import were bad).
    const body: unknown = await res.json().catch(() => undefined);
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, body);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// `user` is the signed-in name, sent as X-User so the server can record who made a change.
const headers = (user?: string): Record<string, string> => ({
  'Content-Type': 'application/json',
  ...(user ? { 'X-User': user } : {}),
});

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: headers(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: headers(user),
    body: JSON.stringify(body),
  });
}

// Guards a form against a second submit (a double click) while the first is still unanswered:
// `disabled={isPending}` only lands on the next render, too late for the second click. Pass the
// submit as a promise (e.g. `() => save.mutateAsync(input)`); its failure is left to the
// mutation's onError.
export function useSubmitOnce() {
  const pending = useRef(false);
  return useCallback((run: () => Promise<unknown>) => {
    if (pending.current) return;
    pending.current = true;
    run()
      .catch(() => undefined)
      .finally(() => {
        pending.current = false;
      });
  }, []);
}

